from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta


class SpyBullishCallAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        spy = self.AddEquity("SPY", Resolution.Minute)
        spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = spy.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )

        self.fast_closes = deque(maxlen=5)
        self.slow_closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.minute_bars = {}
        self.current_bucket = None

        self.entry_ticket = None
        self.entry_symbol = None
        self.entry_price = None

        self.exit_ticket = None
        self.expiration_date = None
        self.no_entry_date = None

    def OnData(self, slice: Slice):
        # Expiration-day protection is evaluated before any possible entry.
        if self.expiration_date is not None:
            today = self.Time.date()

            if today >= self.expiration_date:
                self.no_entry_date = today

                if self.entry_ticket is not None and self._is_open(self.entry_ticket):
                    self.entry_ticket.Cancel("Expiration-day protection")
                    self.entry_ticket = None

                if self.entry_symbol is not None:
                    self._liquidate_option("expiration processing")

        self._evaluate_time_stop()
        self._evaluate_profit_target(slice)

        if self.spy not in slice.Bars:
            return

        bar = slice.Bars[self.spy]
        self._accumulate_minute_bar(bar, slice)

    def _accumulate_minute_bar(self, bar: TradeBar, slice: Slice):
        end_time = self.Time.replace(second=0, microsecond=0)
        if end_time.weekday() >= 5:
            return

        # Regular-session minute bars only.
        if end_time.time() < datetime.strptime("09:31", "%H:%M").time():
            return
        if end_time.time() > datetime.strptime("16:00", "%H:%M").time():
            return

        minute = end_time.minute
        bucket_end_minute = ((minute - 1) // 5 + 1) * 5
        bucket_end = end_time.replace(minute=0) + timedelta(minutes=bucket_end_minute)
        bucket_key = bucket_end

        if self.current_bucket is not None and bucket_key != self.current_bucket:
            self._finish_bucket(self.current_bucket, slice)

        if self.current_bucket != bucket_key:
            self.current_bucket = bucket_key
            self.minute_bars = {}

        self.minute_bars[end_time] = bar

        # The 09:31-09:35 interval therefore ends at 09:35.
        if end_time == bucket_end - timedelta(minutes=0):
            self._finish_bucket(bucket_key, slice)

    def _finish_bucket(self, bucket_end: datetime, slice: Slice):
        if self.current_bucket != bucket_end:
            return

        expected = [
            bucket_end - timedelta(minutes=i)
            for i in range(4, -1, -1)
        ]

        if not all(t in self.minute_bars for t in expected):
            self.minute_bars = {}
            self.current_bucket = None
            return

        close = self.minute_bars[expected[-1]].Close
        self._process_five_minute_close(bucket_end, close, slice)

        self.minute_bars = {}
        self.current_bucket = None

    def _process_five_minute_close(self, bar_end: datetime, close: float, slice: Slice):
        old_fast = self.previous_fast
        old_slow = self.previous_slow

        self.fast_closes.append(close)
        self.slow_closes.append(close)

        if len(self.fast_closes) < 5 or len(self.slow_closes) < 20:
            return

        fast = sum(self.fast_closes) / 5.0
        slow = sum(self.slow_closes) / 20.0

        bullish_cross = (
            old_fast is not None
            and old_slow is not None
            and old_fast <= old_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        if not bullish_cross:
            return

        if not (
            datetime.strptime("09:45", "%H:%M").time()
            <= bar_end.time()
            <= datetime.strptime("14:30", "%H:%M").time()
        ):
            return

        if self.no_entry_date == self.Time.date():
            return

        if self._has_option_holding() or (
            self.entry_ticket is not None and self._is_open(self.entry_ticket)
        ):
            return

        self._enter_from_chain(slice, close)

    def _enter_from_chain(self, slice: Slice, spy_price: float):
        if not slice.OptionChains:
            self.Debug("Skipped entry: no option chain.")
            return

        today = self.Time.date()
        minimum_expiry = today + timedelta(days=7)
        candidates = []

        for chain in slice.OptionChains.Values:
            for contract in chain.Contracts.Values:
                expiry = contract.Expiry.date()

                if expiry < minimum_expiry:
                    continue
                if contract.Right != OptionRight.Call:
                    continue
                if contract.Strike < 1.01 * spy_price:
                    continue

                candidates.append(contract)

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        selected_expiry = min(c.Expiry.date() for c in candidates)
        candidates = [
            c for c in candidates
            if c.Expiry.date() == selected_expiry
        ]

        selected = min(
            candidates,
            key=lambda c: (c.Strike, str(c.Symbol))
        )

        self.entry_symbol = selected.Symbol
        self.expiration_date = selected_expiry
        self.entry_price = None

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Entry submitted: {0}, expiry {1}, strike {2}".format(
                selected.Symbol, selected_expiry, selected.Strike
            )
        )

    def _evaluate_profit_target(self, slice: Slice):
        if self.entry_symbol is None or self.entry_price is None:
            return
        if not self._has_option_holding():
            return
        if self.exit_ticket is not None and self._is_open(self.exit_ticket):
            return

        if not slice.BidAskBars.ContainsKey(self.entry_symbol):
            return

        quote = slice.BidAskBars[self.entry_symbol]
        if quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self._cancel_exit_order()
            quantity = self.Portfolio[self.entry_symbol].Quantity
            if quantity != 0:
                self.exit_ticket = self.MarketOrder(
                    self.entry_symbol,
                    -quantity
                )
                self.Debug("Exit submitted: 50% profit target.")

    def _evaluate_time_stop(self):
        if self.entry_symbol is None or self.expiration_date is None:
            return
        if not self._has_option_holding():
            return
        if self.exit_ticket is not None and self._is_open(self.exit_ticket):
            return

        previous_trading_day = self._previous_trading_day(
            self.expiration_date
        )

        if (
            self.Time.date() == previous_trading_day
            and self.Time.time() >= datetime.strptime(
                "15:45", "%H:%M"
            ).time()
        ):
            self._cancel_exit_order()
            quantity = self.Portfolio[self.entry_symbol].Quantity
            if quantity != 0:
                self.exit_ticket = self.MarketOrder(
                    self.entry_symbol,
                    -quantity
                )
                self.Debug("Exit submitted: pre-expiration time stop.")

    def _liquidate_option(self, reason: str):
        if self.entry_symbol is None:
            return
        if self.exit_ticket is not None and self._is_open(self.exit_ticket):
            return

        quantity = self.Portfolio[self.entry_symbol].Quantity
        if quantity != 0:
            self.exit_ticket = self.MarketOrder(
                self.entry_symbol,
                -quantity
            )
            self.Debug("Exit submitted: {0}.".format(reason))

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.entry_price = order_event.FillPrice
                    self.Debug(
                        "Entry filled: {0} at {1}.".format(
                            self.entry_symbol, self.entry_price
                        )
                    )
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                    OrderStatus.None_
                ):
                    self.entry_ticket = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug("Option exit filled.")
                    self.exit_ticket = None
                    self.entry_ticket = None
                    self.entry_symbol = None
                    self.entry_price = None
                    self.expiration_date = None

    def OnAssignmentOrder(self, assignment_order):
        self.Debug("Unexpected option exercise or assignment handled.")

        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0:
            self.MarketOrder(self.spy, -quantity)
            self.Debug("Liquidated unexpected SPY equity position.")

        self.no_entry_date = self.Time.date()

    def _cancel_exit_order(self):
        if self.exit_ticket is not None and self._is_open(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing exit order")
            self.exit_ticket = None

    def _has_option_holding(self):
        return (
            self.entry_symbol is not None
            and self.Portfolio[self.entry_symbol].Invested
        )

    @staticmethod
    def _is_open(ticket):
        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    @staticmethod
    def _previous_trading_day(expiration_date):
        day = expiration_date - timedelta(days=1)
        while day.weekday() >= 5:
            day -= timedelta(days=1)
        return day
