from QuantConnect import *
from QuantConnect.Algorithm import QCAlgorithm
from QuantConnect.Orders import OrderStatus
from QuantConnect.Securities.Option import OptionRight


class SpyLongCallAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda u: u.IncludeWeeklys()
                       .Strikes(-200, 200)
                       .Expiration(0, 365)
        )

        self.fast_period = 5
        self.slow_period = 20

        self.closes = []
        self.previous_fast = None
        self.previous_slow = None

        self.current_day = None
        self.current_bucket_end = None
        self.bucket_bars = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.no_entry_today = None

    def OnData(self, slice: Slice):
        self._handle_unexpected_spy_position()
        self._handle_expiration_safety()
        self._evaluate_exit(slice)

        if "SPY" not in slice.Bars:
            return

        bar = slice.Bars["SPY"]
        self._process_minute_bar(bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        local_end = bar.EndTime
        day = local_end.date()

        if self.current_day != day:
            self.current_day = day
            self.current_bucket_end = None
            self.bucket_bars = {}

        # Regular-session bars only. Minute bar EndTime is already in algorithm time.
        if local_end.time() < datetime.strptime("09:31", "%H:%M").time():
            return
        if local_end.time() > datetime.strptime("16:00", "%H:%M").time():
            return

        minute = local_end.minute
        bucket_end_minute = ((minute - 1) // 5 + 1) * 5
        bucket_hour = local_end.hour + bucket_end_minute // 60
        bucket_end_minute %= 60

        bucket_end = local_end.replace(
            hour=bucket_hour,
            minute=bucket_end_minute,
            second=0,
            microsecond=0
        )

        if self.current_bucket_end is not None and bucket_end != self.current_bucket_end:
            self._finish_bucket(self.current_bucket_end, slice)

        if self.current_bucket_end != bucket_end:
            self.current_bucket_end = bucket_end
            self.bucket_bars = {}

        self.bucket_bars[local_end] = bar

        if local_end == bucket_end:
            self._finish_bucket(bucket_end, slice)

    def _finish_bucket(self, bucket_end: datetime, slice: Slice):
        if not self.bucket_bars:
            return

        expected_times = [
            bucket_end - timedelta(minutes=i)
            for i in range(4, -1, -1)
        ]

        # A missing minute means there is no valid five-minute bar.
        if set(self.bucket_bars.keys()) != set(expected_times):
            self.bucket_bars = {}
            return

        bars = [self.bucket_bars[t] for t in expected_times]

        consolidated = TradeBar(
            bars[0].Symbol,
            bars[0].Time,
            bars[-1].EndTime,
            bars[0].Open,
            max(x.High for x in bars),
            min(x.Low for x in bars),
            bars[-1].Close,
            sum(x.Volume for x in bars)
        )

        self.bucket_bars = {}
        self._process_five_minute_bar(consolidated, slice)

    def _process_five_minute_bar(self, bar: TradeBar, slice: Slice):
        self.closes.append(float(bar.Close))

        if len(self.closes) > self.slow_period:
            self.closes.pop(0)

        if len(self.closes) < self.slow_period:
            return

        current_fast = sum(self.closes[-self.fast_period:]) / self.fast_period
        current_slow = sum(self.closes[-self.slow_period:]) / self.slow_period

        previous_fast = self.previous_fast
        previous_slow = self.previous_slow

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        if previous_fast is None or previous_slow is None:
            return

        bullish_cross = (
            previous_fast <= previous_slow
            and current_fast > current_slow
        )

        bar_time = bar.EndTime.time()
        eligible_start = datetime.strptime("09:45", "%H:%M").time()
        eligible_end = datetime.strptime("14:30", "%H:%M").time()

        if not bullish_cross:
            return
        if not (eligible_start <= bar_time <= eligible_end):
            return
        if self.no_entry_today == self.Time.date():
            return
        if self._option_position_exists() or self._entry_order_open():
            return

        self._enter_from_current_chain(slice)

    def _enter_from_current_chain(self, slice: Slice):
        chains = self._get_chains(slice)

