        close = float(bar.Close)
        if close <= 0:
            return

        old_fast = self.previous_fast
        old_slow = self.previous_slow

        self.closes.append(close)

        values = list(self.closes)
        self.previous_fast = (
            sum(values[-5:]) / 5.0 if len(values) >= 5 else None
        )
        self.previous_slow = (
            sum(values) / 20.0 if len(values) >= 20 else None
        )

        if (
            old_fast is not None and
            old_slow is not None and
            self.previous_fast is not None and
            self.previous_slow is not None and
            old_fast <= old_slow and
            self.previous_fast > self.previous_slow
        ):
            self.pending_signal_end = end

    def OnData(self, slice):
        spy_holding = self.Portfolio[self.spy]
        if spy_holding.Invested:
            self.Debug("Unexpected exercise/assignment: liquidating SPY equity")
            self.MarketOrder(self.spy, -spy_holding.Quantity)

        current_date = self.Time.date()

        if self.held_option is not None:
            expiry_date = self.held_option.ID.Date.date()

            if current_date >= expiry_date:
                self.expiration_blocked_date = current_date
                self.LiquidateOption("expiration processing")
            else:
                prior_trading_day = self.PreviousTradingDay(expiry_date)
                stop_time = datetime.strptime("15:45", "%H:%M").time()

                if (
                    current_date == prior_trading_day and
                    self.Time.time() >= stop_time
                ):
                    self.LiquidateOption("expiration time stop")
                else:
                    self.CheckProfitTarget(slice)

        if (
            self.pending_signal_end is not None and
            self.pending_signal_end != self.last_processed_signal_end
        ):
            signal_end = self.pending_signal_end
            self.pending_signal_end = None
            self.last_processed_signal_end = signal_end

            entry_start = datetime.strptime("09:45", "%H:%M").time()
            entry_end = datetime.strptime("14:30", "%H:%M").time()

            if entry_start <= signal_end.time() <= entry_end:
                if self.expiration_blocked_date != current_date:
                    self.TryEnter(slice)

    def TryEnter(self, slice):
        if self.IsOrderOpen(self.entry_ticket):
            return

        if self.HasOptionHolding():
            return

        chain = None
        for candidate in slice.OptionChains.Values:
            chain = candidate
            break

        if chain is None:
            self.Debug("Skipped selection: no option chain")
            return

        today = self.Time.date()
        minimum_expiry = today + timedelta(days=7)

        contracts = list(chain.Contracts.Values)
        expiries = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("Skipped selection: no expiration at least 7 days out")
            return

        selected_expiry = expiries[0]
        spy_price = float(self.Securities[self.spy].Price)

        if spy_price <= 0:
            self.Debug("Skipped selection: invalid SPY price")
            return

        eligible = [
            contract for contract in contracts
            if (
                contract.Expiry.date() == selected_expiry and
                contract.Right == OptionRight.Call and
                contract.Strike >= 1.01 * spy_price
            )
        ]

        if not eligible:
            self.Debug(
                "Skipped selection: no eligible call at selected expiration"
            )
            return

        selected = sorted(
            eligible,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.held_option = selected.Symbol
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)

        self.Debug("Entry submitted: " + str(selected.Symbol))

    def CheckProfitTarget(self, slice):
        if self.entry_price is None:
            return

        if self.IsOrderOpen(self.exit_ticket):
            return

        contract = None

        for chain in slice.OptionChains.Values:
            if self.held_option in chain.Contracts:
                contract = chain.Contracts[self.held_option]
                break

        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self.LiquidateOption("50% profit target")

    def LiquidateOption(self, reason):
        if self.held_option is None:
            return

        if self.IsOrderOpen(self.exit_ticket):
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        if self.IsOrderOpen(self.entry_ticket):
            self.Transactions.CancelOrder(self.entry_ticket.OrderId)

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity
        )

        self.Debug(
            "Exit submitted (" + reason + "): " + str(self.held_option)
        )

    def OnOrderEvent(self, order_event):
        if (
            self.entry_ticket is not None and
            order_event.OrderId == self.entry_ticket.OrderId
        ):
            if (
                order_event.Status == OrderStatus.Filled and
                order_event.FillQuantity > 0
            ):
                self.entry_price = float(order_event.FillPrice)
                self.Debug("Entry filled at " + str(self.entry_price))

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_ticket = None
                self.held_option = None
                self.entry_price = None

        if getattr(order_event, "IsAssignment", False):
            self.Debug("Unexpected exercise/assignment order event")

            holding = self.Portfolio[self.spy]
            if holding.Invested:
                self.MarketOrder(self.spy, -holding.Quantity)

        if (
            self.exit_ticket is not None and
            order_event.OrderId == self.exit_ticket.OrderId and
            order_event.Status == OrderStatus.Filled
        ):
            self.Debug("Exit filled: " + str(self.held_option))

            self.entry_ticket = None
            self.exit_ticket = None
            self.held_option = None
            self.entry_price = None

    def HasOptionHolding(self):
        for security in self.Securities.Values:
            if (
                security.Symbol.SecurityType == SecurityType.Option and
                security.Holdings.Invested
            ):
                return True

        return False

    def IsOrderOpen(self, ticket):
        if ticket is None:
