            return

        if current_date >= self.expiration_date:
            self.block_entry_date = current_date
            self._submit_exit("expiration protection")

    def _handle_unexpected_equity_position(self, current_date):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity == 0:
            return

        if self._assignment_handled_date != current_date:
