        spy_quantity = self.Portfolio[self.spy].Quantity
        if spy_quantity != 0:
            if self.blocked_entry_date != today:
                self.Debug(
                    f"Unexpected SPY equity position detected; liquidating {spy_quantity} shares"
                )
            self.blocked_entry_date = today
            self.MarketOrder(
