        if self.current_slice is None:
            return

        spy_price = self.Securities[self.spy].Price
        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price")
            return

        chains = list(self.current_slice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped entry: no option chain")
            return

        algorithm_date = self.Time.date()
        earliest_expiry = algorithm_date + timedelta(days=7)

        candidates = []
        for chain in chains:
