            self.held_option,
            -quantity,
            tag=reason
        )

        self.Debug(f"Exit submitted: {self.held_option} ({reason})")

    def IsEntryOrderOpen(self):
        return self.entry_ticket is not None and self.IsOrderOpen(self.entry_ticket)

    def IsOrderOpen(self, ticket):
        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def IsExpirationPrecedingTradingDay(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)

        while not self.IsTradingDay(candidate):
            candidate -= timedelta(days=1)

        return self.Time.date() == candidate

    def IsTradingDay(self, date_value):
        dt = datetime.combine(date_value, time.min)
        return self.Securities[self.spy].Exchange.Hours.IsDateOpen(dt)

    def OnOrderEvent(self, order_event: OrderEvent):
        if getattr(order_event, "IsAssignment", False):
            self.blocked_entry_date = self.Time.date()
            self.Debug("Unexpected option exercise or assignment detected")

