from AlgorithmImports import *
from datetime import datetime, timedelta, time
from collections import deque


class SpyCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        equity = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        )
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = option.Symbol
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 730)
        )

        self.fast_period = 5
        self.slow_period = 20
        self.closes = deque(maxlen=self.slow_period)

        self.aggregating_date = None
        self.aggregating_end = None
        self.minute_bars = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.no_entry_date = None

    def OnData(self, slice: Slice):
        today = self.Time.date()

        # Handle unexpected SPY equity resulting from exercise or assignment.
        spy_quantity = self.Portfolio[self.spy].Quantity
        if spy_quantity != 0:
            if self.no_entry_date != today:
                self.Debug(
                    f"Unexpected SPY equity position detected: "
                    f"{spy_quantity} shares; liquidating."
                )
            self.no_entry_date = today

            if not self._open_order_exists(self.spy):
                self.MarketOrder(
                    self.spy,
                    -spy_quantity,
                    tag="Liquidate unexpected exercise/assignment equity"
                )

        # Process exits on every minute Slice.
        self._process_option_exits(slice)

        # Build an aligned five-minute bar from actual minute bars only.
        if self.spy not in slice.Bars:
            return

        minute_bar = slice.Bars[self.spy]
        self._process_minute_bar(minute_bar, slice)

    def _process_minute_bar(self, minute_bar: TradeBar, slice: Slice):
        end = minute_bar.EndTime
        current_date = end.date()
        current_time = end.time()

        # Use regular-session minute data only.
        if current_time < time(9, 30) or current_time > time(16, 0):
            return

        minute_number = end.hour * 60 + end.minute
        minutes_from_open = minute_number - (9 * 60 + 30)
        bucket_number = (minutes_from_open - 1) // 5
        bucket_end_minutes = (9 * 60 + 30) + (bucket_number + 1) * 5
        bucket_end = datetime(
            current_date.year,
            current_date.month,
            current_date.day,
            bucket_end_minutes // 60,
            bucket_end_minutes % 60
        )

        if (
            self.aggregating_end is not None
            and (
                current_date != self.aggregating_date
                or bucket_end != self.aggregating_end
            )
        ):
            self._finalize_five_minute_bar(slice)

            self.minute_bars = {}
            self.aggregating_date = None
            self.aggregating_end = None

        if self.aggregating_end is None:
            self.aggregating_date = current_date
            self.aggregating_end = bucket_end

        self.minute_bars[end] = minute_bar

        if len(self.minute_bars) == 5:
            self._finalize_five_minute_bar(slice)
            self.minute_bars = {}
            self.aggregating_date = None
            self.aggregating_end = None

    def _finalize_five_minute_bar(self, slice: Slice):
        if self.aggregating_end is None:
            return

        expected = [
            self.aggregating_end - timedelta(minutes=i)
            for i in range(5, 0, -1)
        ]

        # Missing minute data means the five-minute bar is missing.
        if any(timestamp not in self.minute_bars for timestamp in expected):
            return

        bars = [self.minute_bars[timestamp] for timestamp in expected]
        close = bars[-1].Close

        previous_fast = None
        previous_slow = None

        if len(self.closes) >= self.slow_period:
            previous_fast = sum(list(self.closes)[-self.fast_period:]) / self.fast_period
            previous_slow = sum(self.closes) / self.slow_period

        self.closes.append(close)

        if len(self.closes) < self.slow_period:
            return

        current_fast = sum(list(self.closes)[-self.fast_period:]) / self.fast_period
        current_slow = sum(self.closes) / self.slow_period

        bullish_cross = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        bar_end_time = self.aggregating_end.time()
        eligible_time = time(9, 45) <= bar_end_time <= time(14, 30)

        if bullish_cross and eligible_time:
            self._evaluate_entry(slice, close)

    def _evaluate_entry(self, slice: Slice, spy_price: float):
        today = self.Time.date()

        if self.no_entry_date == today:
            return

        if self.held_option is not None:
            return

        if self._entry_order_is_open():
            return

        chain = None
        if self.option_symbol in slice.OptionChains:
            chain = slice.OptionChains[self.option_symbol]

        if chain is None:
            self.Debug("Entry skipped: no option chain in current Slice.")
            return

        minimum_expiry = today + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Entry skipped: no expiration at least seven days out.")
            return

        selected_expiry = expirations[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract
            for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"Entry skipped: no qualifying call for {selected_expiry}."
            )
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.held_option = selected.Symbol
        self.entry_price = None
        self.exit_ticket = None

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag=f"Buy SPY call {selected.Symbol}"
        )

        self.Debug(f"Entry submitted: {selected.Symbol}")

    def _process_option_exits(self, slice: Slice):
        if self.held_option is None:
            return

        today = self.Time.date()
        current_time = self.Time.time()
        held_security = self.Portfolio[self.held_option]

        expiration_date = self._get_held_expiration_date(slice)

        # Never intentionally hold through expiration.
        if expiration_date is not None and today >= expiration_date:
            self.no_entry_date = today
            self._submit_exit("Expiration liquidation")
            return

        # Time stop on the immediately preceding trading day.
        if (
            expiration_date is not None
            and today == self._previous_trading_day(expiration_date)
